                    inputs = { hybrid_run_id: String(fd.get('hybrid_run_id') ?? '') || null, market: state.data.market, brief: String(fd.get('brief') ?? ''), mode: String(fd.get('mode') ?? 'local'), consent_to_external_processing: fd.get('consent') === 'on', cross_examination_rounds: Number(fd.get('cross_examination_rounds') ?? 1), evidence_run_ids: String(fd.get('evidence_run_ids') ?? '').split(',').map(x => x.trim()).filter(Boolean) };
                    path = 'council/review';
